Con herencia

class Animal:
    def __init__(self, nombre): self.nombre = nombre
class Perro(Animal):
    def hablar(self): return f"{self.nombre}: ¡Guau!"
class Gato(Animal):
    def hablar(self): return f"{self.nombre}: ¡Miau!"

for animal in [Perro("Rex"), Gato("Tom"), Perro("Max")]:
    print(animal.hablar())

Rex: ¡Guau!
Tom: ¡Miau!
Max: ¡Guau!



El ciclo no sabe ni le importa de qué tipo es cada animal. Mostrar la animación del capítulo 6.

Sin polimorfismo…
for animal in animales:
    if isinstance(animal, Perro):
        print("¡Guau!")
    elif isinstance(animal, Gato):
        print("¡Miau!")
    elif ...           # ¡crece con cada tipo nuevo!

Cada vez que agregas un tipo hay que tocar este código. Con polimorfismo, cada clase sabe responder.

Ejemplo: formas de pago






classDiagram
    class Carrito {
        +pagar(metodo_pago)
    }
    class TarjetaCredito {
        +procesar_pago(monto)
    }
    class PayPal {
        +procesar_pago(monto)
    }
    class Efectivo {
        +procesar_pago(monto)
    }
    Carrito ..&gt; TarjetaCredito : usa
    Carrito ..&gt; PayPal : usa
    Carrito ..&gt; Efectivo : usa







Las tres clases no tienen padre común. Lo único que comparten es el método procesar_pago(monto).

El código del carrito

class Efectivo:
    def procesar_pago(self, monto): print(f"Recibo ${monto} en efectivo")
class PayPal:
    def procesar_pago(self, monto): print(f"Cobro ${monto} con PayPal")

def pagar(total, metodo):
    metodo.procesar_pago(total)     # no sabe qué método es

pagar(150, Efectivo())
pagar(80, PayPal())

Recibo $150 en efectivo
Cobro $80 con PayPal



pagar() funciona con cualquier objeto que tenga procesar_pago. Preguntar: ¿qué pasa si mañana aceptamos pagos con vales?

Los métodos protegen las reglas

class Cuenta:
    def retirar(self, cantidad):
        if cantidad &gt; self.saldo:
            print("Fondos insuficientes")
        else:
            self.saldo -= cantidad

c = Cuenta(); c.saldo = 100
c.retirar(500)

Fondos insuficientes



Primer vistazo al encapsulamiento (tema 5): la lógica de negocio vive en el método.

Métodos que llaman a otros métodos

class Robot:
    def adelante(self):
        print("→ adelante")
    def atras(self):
        print("← atrás")
    def bailar(self):
        self.adelante()
        self.atras()

Robot().bailar()

→ adelante
← atrás



Para llamar a otro método del mismo objeto también se usa self.

Interfaces
Clase abstracta sólo con métodos abstractos: define qué hacer, no cómo.

class Volador(ABC):
    @abstractmethod
    def volar(self): ...

class Nadador(ABC):
    @abstractmethod
    def nadar(self): ...


Python no tiene la palabra interface como Java; se simula con una ABC que sólo tiene métodos abstractos.

Valores por defecto

class Cuenta:
    def __init__(self, titular, saldo=0, tipo="Ahorro"):
        self.titular, self.saldo, self.tipo = titular, saldo, tipo

for c in [Cuenta("Ana"), Cuenta("Luis", 1000, "Corriente")]:
    print(c.titular, c.saldo, c.tipo)

Ana 0 Ahorro
Luis 1000 Corriente



Los parámetros con valor por defecto van al final.

Validar al construir

class Persona:
    def __init__(self, nombre, edad):
        if not 0 &lt;= edad &lt;= 150:
            raise ValueError("La edad debe estar entre 0 y 150")
        self.nombre, self.edad = nombre, edad

try:
    Persona("Ana", 200)
except ValueError as e:
    print("ValueError:", e)

ValueError: La edad debe estar entre 0 y 150



Si los datos son inválidos, el objeto ni siquiera llega a existir. Mejor fallar pronto.

Privado en acción

class Persona:
    def __init__(self, nombre, saldo):
        self.nombre = nombre
        self.__saldo = saldo

ana = Persona("Ana", 10000)
try:
    print(ana.__saldo)
except AttributeError as e:
    print("Error:", e)

Error: 'Persona' object has no attribute '__saldo'



Fuera de la clase, ana.__saldo no existe con ese nombre. Dentro de los métodos de la clase sí se puede usar normalmente.

Acceso controlado con métodos

class Cuenta:
    def __init__(self, saldo):
        self.__saldo = saldo
    def retirar(self, cantidad):
        if 0 &lt; cantidad &lt;= self.__saldo:
            self.__saldo -= cantidad
        else:
            print("Operación rechazada")
    def consultar(self):
        return self.__saldo

c = Cuenta(1000); c.retirar(5000); print(c.consultar())

Operación rechazada
1000



El saldo sólo cambia a través de retirar(), que verifica las reglas. Ya no es posible dejarlo negativo desde fuera.

@property

class Persona:
    def __init__(self, edad):
        self.__edad = edad

    @property
    def edad(self):            # getter
        return self.__edad

p = Persona(25)
print(p.edad)                  # ¡sin paréntesis!

25



@property convierte un método en algo que se lee como atributo. El código que usa la clase no nota la diferencia.

@x.setter con validación

class Persona:
    def __init__(self, edad):
        self.edad = edad              # pasa por el setter
    @property
    def edad(self):
        return self.__edad
    @edad.setter
    def edad(self, valor):
        if not 0 &lt;= valor &lt;= 150:
            raise ValueError("Edad inválida")
        self.__edad = valor


Se usa como un atributo normal, pero cada asignación pasa por la validación.

Herencia mal usada
class Motor:
    def encender(self): ...

class Coche(Motor):      # ✗ un coche NO ES un motor
    pass
class Coche:
    def __init__(self):
        self.motor = Motor()   # ✓ un coche TIENE un motor

Si la frase “un X es un Y” suena absurda, no es herencia.

Composición = flexibilidad

class MotorGasolina:
    def arrancar(self): return "brum brum"
class MotorElectrico:
    def arrancar(self): return "zzzz"

class Coche:
    def __init__(self, motor): self.motor = motor
    def arrancar(self): print(self.motor.arrancar())

c = Coche(MotorGasolina()); c.arrancar()
c.motor = MotorElectrico(); c.arrancar()     # cambio en tiempo de ejecución

brum brum
zzzz



Con herencia el “tipo de motor” quedaría fijo en la jerarquía. Con composición se cambia la pieza.

Producto: abstracto y encapsulado
class Producto(ABC):
    def __init__(self, nombre, precio, stock):
        self.__nombre, self.__precio, self.__stock = nombre, precio, stock

    @property
    def precio(self):
        return self.__precio

    @abstractmethod
    def calcular_precio_final(self): ...

Abstracción (no existe un “producto genérico”) + encapsulamiento (precio validado por propiedad).

Polimorfismo en el precio
class ProductoElectronico(Producto):
    def calcular_precio_final(self):
        return self.precio * 1.16          # IVA

class ProductoRopa(Producto):
    def calcular_precio_final(self):
        return self.precio * 0.90          # temporada

class ProductoAlimento(Producto):
    def calcular_precio_final(self):
        return self.precio * (0.5 if self.dias_para_caducar() &lt;= 3 else 1)
El carrito sólo llama producto.calcular_precio_final().

Cada tipo de producto calcula su precio a su manera. El carrito y la orden no necesitan saber de qué tipo es cada producto.

Métodos de pago: una interfaz
class MetodoPago(ABC):
    @abstractmethod
    def procesar_pago(self, monto): ...
    @abstractmethod
    def validar(self): ...

class PayPal(MetodoPago):
    def validar(self):
        return "@" in self.email
    def procesar_pago(self, monto):
        ...

La tienda depende de MetodoPago, no de PayPal ni de TarjetaCredito. Agregar un método nuevo no la modifica.

El carrito: composición
class Carrito:
    def __init__(self):
        self.__items = []                      # el carrito posee sus items

    def agregar_producto(self, producto, cantidad=1):
        self.__items.append(ItemCarrito(producto, cantidad))

    def calcular_total(self):
        return sum(i.obtener_subtotal() for i in self.__items)

    def __len__(self):                         # método especial
        return len(self.__items)

Los ItemCarrito los crea el carrito y no tienen sentido fuera de él. len permite escribir len(carrito).

